fn titles(ds: Array<Draft>) -> Result<Array<String>, FormError> {
  ds |> .try_map((d) => non_empty("title", d.title))   // 最初の Err で抜ける。JS は for ループ、Rust は collect::<Result<Vec<_>,_>>()
}

fn first_len(todos: Array<Todo>) -> Option<i32> {
  find(todos, 1)?.note?.len()   // Rust と同じく (e?).f の意味。TS の意味なら型が Option<…> になるので型検査で分かる
}

fn maybe_title(r: Result<Todo, FormError>) -> Option<String> {
  Some(r.ok()?.title)   // match を書かずに、エラーを捨てる
}

type Boxed<T> = { value?: T }        // error: an optional field needs a concrete type (write `value: Option<T>` for a generic field)

